/* ═══════════════════════════════════════════════════════════ */
/* INTRO SECTION — Opening prologue before Chapter I            */
/* ═══════════════════════════════════════════════════════════ */

.bpt-intro {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    padding: clamp(48px, 10vw, 120px) clamp(24px, 8vw, 80px);
    background: var(--color-rice-paper);
    overflow: hidden;
}

/* Subtle radial glow behind the content */
.bpt-intro::before {
    content: "";
    position: absolute;
    width: clamp(320px, 50vw, 600px);
    height: clamp(320px, 50vw, 600px);
    border-radius: 50%;
    background: radial-gradient(
        circle,
        rgba(245, 222, 179, 0.1) 0%,
        transparent 70%
    );
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    pointer-events: none;
}

.bpt-intro__inner {
    position: relative;
    width: 100%;
    text-align: center;
    z-index: 1;
}

/* ─── Title ─── */
.bpt-intro__title {
    font-family: "DNS Gibsons One", "Oswald", sans-serif;
    font-size: clamp(4rem, 10vw, 7.2rem);
    font-weight: 700;
    line-height: 1.15;
    color: var(--color-betel-leaf-green);
    margin: 0 0 clamp(20px, 3vw, 36px);
    word-break: keep-all;
}

/* ─── Decorative line ─── */
.bpt-intro__line {
    display: block;
    width: 0;
    height: 2px;
    margin: 0 auto clamp(28px, 4vw, 48px);
    background: linear-gradient(
        90deg,
        transparent,
        var(--color-sticky-rice-gold, #f5deb3),
        transparent
    );
    transition: width 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}

.bpt-intro.bpt-visible .bpt-intro__line {
    width: clamp(80px, 20vw, 160px);
}

/* ─── Body text container ─── */
.bpt-intro__body {
    font-family: "Vollkorn", "PT Serif", Georgia, serif;
    font-size: clamp(1.2rem, 2vw, 1.65rem);
    font-weight: 700;
    line-height: 1.7;
    color: var(--color-ink);
    margin: 0;
    max-width: 800px;
    margin-inline: auto;
}

/* ─── Per-line typewriter ─── */
.bpt-intro__line-text {
    display: block;
    clip-path: inset(0 100% 0 0);
    will-change: clip-path;
}

/* Each line: 1s reveal, staggered by 1s */
.bpt-intro.bpt-visible .bpt-intro__line-text:nth-child(1) {
    animation: bpt-line-reveal 1s steps(104, end) 0.2s forwards;
}
.bpt-intro.bpt-visible .bpt-intro__line-text:nth-child(2) {
    animation: bpt-line-reveal 1s steps(121, end) 1.2s forwards;
}
.bpt-intro.bpt-visible .bpt-intro__line-text:nth-child(3) {
    animation: bpt-line-reveal 1s steps(140, end) 2.2s forwards;
}

@keyframes bpt-line-reveal {
    to {
        clip-path: inset(0 0% 0 0);
    }
}

/* ─── Entrance animations (initial states) ─── */
.bpt-intro__title {
    opacity: 0;
    transform: translateY(28px);
    transition:
        opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1),
        transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.bpt-intro__line {
    opacity: 1;
}

/* ─── Visible states ─── */
.bpt-intro.bpt-visible .bpt-intro__title {
    opacity: 1;
    transform: translateY(0);
}

/* ─── Reduced motion ─── */
@media (prefers-reduced-motion: reduce) {
    .bpt-intro__title,
    .bpt-intro__line {
        opacity: 1 !important;
        transform: none !important;
        transition: none !important;
    }
    .bpt-intro__line {
        width: clamp(80px, 20vw, 160px) !important;
    }
    .bpt-intro__line-text {
        clip-path: inset(0 0% 0 0) !important;
        animation: none !important;
    }
}

/* CHUONG II - NGHE NHAN - ELEMENT LEVEL ANIMATIONS */

.bpt-kicker { opacity: 0; transform: translateY(20px); transition: opacity 0.5s ease, transform 0.5s cubic-bezier(0.16, 1, 0.3, 1); }
.bpt-kicker.is-visible { opacity: 1; transform: translateY(0); }

.bpt-prose p { opacity: 0; transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.16, 1, 0.3, 1); }

.bpt-prose p[data-anim="scale-pop"] { transform: scale(0.8); }
.bpt-prose p[data-anim="scale-pop"].is-visible { opacity: 1; transform: scale(1); }

.bpt-prose p[data-anim="slide-up"] { transform: translateY(40px); }
.bpt-prose p[data-anim="slide-up"].is-visible { opacity: 1; transform: translateY(0); }

.bpt-prose p[data-anim="slide-right"] { transform: translateX(-60px); }
.bpt-prose p[data-anim="slide-right"].is-visible { opacity: 1; transform: translateX(0); }

.bpt-prose p[data-anim="slide-left"] { transform: translateX(60px); }
.bpt-prose p[data-anim="slide-left"].is-visible { opacity: 1; transform: translateX(0); }

.bpt-prose p[data-anim="rotate-in"] { transform: rotate(-5deg) translateY(30px); }
.bpt-prose p[data-anim="rotate-in"].is-visible { opacity: 1; transform: rotate(0) translateY(0); }

.bpt-prose p[data-anim="fade-zoom"] { transform: scale(0.95); }
.bpt-prose p[data-anim="fade-zoom"].is-visible { opacity: 1; transform: scale(1); }

/* Force scale animation for no-cascade sections */
.bpt-no-cascade .bpt-prose p,
.bpt-no-cascade.bpt-prose p {
  transform: scale(0.8);
}
.bpt-no-cascade .bpt-prose p.is-visible,
.bpt-no-cascade.bpt-prose p.is-visible {
  opacity: 1;
  transform: scale(1);
}

.bpt-ca-dao { opacity: 0; transform: translateY(30px) scale(0.95); transition: opacity 0.7s ease, transform 0.7s cubic-bezier(0.16, 1, 0.3, 1); }
.bpt-ca-dao.is-visible { opacity: 1; transform: translateY(0) scale(1); }

